                KeyCode::Esc => {
                    self.mode = Mode::Pool(PoolMode::View {
                        selected: Some(worker),
                    });
                }
                KeyCode::Backspace => {
                    buffer.pop();
                    self.mode = Mode::Pool(PoolMode::AliasInput { worker, buffer });
                }
